package com.aig.fifth432
import android.app.Activity
import android.graphics.Color
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.*
import com.aig.core.ui.R as UiR
import com.aig.core.ui.RgbGlassButton
import com.aig.core.ui.UiKit
import com.aig.feature.home.HomeFeatureView
import com.aig.feature.cad.CadFeatureView
import com.aig.feature.cam.CamFeatureView
import com.aig.feature.nc.NcFeatureView
import com.aig.renderer.unity.api.*
class MainActivity:Activity(){private lateinit var content:FrameLayout;private val nav=linkedMapOf<String,RgbGlassButton>();override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);window.statusBarColor=Color.rgb(2,4,7);window.navigationBarColor=Color.rgb(2,4,7);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(Color.rgb(2,4,7));setPadding(UiKit.dp(this@MainActivity,8),UiKit.dp(this@MainActivity,6),UiKit.dp(this@MainActivity,8),UiKit.dp(this@MainActivity,6))};val header=UiKit.panel(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;addView(UiKit.label(this@MainActivity,"AIG-II  |  AIG CNC",22f),LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f));addView(UiKit.label(this@MainActivity,"434.0.0",13f))};root.addView(header);root.addView(UiKit.statusLabel(this,"0.001 mm • 本機離線可用 • Android 官方 Runtime"));val names=listOf("HOME","CAD","CAM","SIM","3AX","4AX","5AX","6AX","NC","AI");repeat(2){r->val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};names.drop(r*5).take(5).forEach{name->nav[name]=UiKit.addWeightedButton(row,name){open(name)}};root.addView(row)};content=FrameLayout(this).apply{setBackgroundColor(Color.rgb(2,4,7))};root.addView(content,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f));setContentView(root);open("HOME")};private fun open(name:String){nav.forEach{(k,b)->b.setActive(k==name)};val v:View=when(name){"HOME"->HomeFeatureView.create(this);"CAD"->CadFeatureView.create(this);"CAM"->CamFeatureView.create(this);"NC"->NcFeatureView.create(this);"SIM"->machinePage(name,UiR.drawable.aig_sim,MachineMode.SIM, emptyList(),false);"3AX"->machinePage(name,UiR.drawable.aig_axis3,MachineMode.AXIS3,emptyList(),false);"4AX"->machinePage(name,UiR.drawable.aig_axis4,MachineMode.AXIS4,listOf('A'),false);"5AX"->machinePage(name,UiR.drawable.aig_axis5,MachineMode.AXIS5,listOf('A','B'),false);"6AX"->machinePage(name,UiR.drawable.aig_machine,MachineMode.AXIS6,listOf('A','B','C'),true);else->offlineAi()};content.removeAllViews();content.addView(v,FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT,FrameLayout.LayoutParams.MATCH_PARENT))};private fun machinePage(name:String,skin:Int,mode:MachineMode,axes:List<Char>,verticalOnly:Boolean):View{val root=UiKit.column(this);root.addView(UiKit.skinBanner(this,skin,68));val status=UiKit.statusLabel(this,if(mode==MachineMode.SIM)"SIM • OpenGL ES • 真數值材料移除 0.000 mm³" else "$name${if(verticalOnly)" • VERTICAL ONLY" else ""} • OpenGL ES • 0.001 mm");root.addView(status);val gl=MachineGlView(this,mode);gl.statusListener={s->status.text=if(verticalOnly)"$s • VERTICAL ONLY" else s};root.addView(gl,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f));if(mode==MachineMode.SIM){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};UiKit.addWeightedButton(row,"RESET MATERIAL"){gl.resetSimulation();status.text="SIM • RESET • 0.000 mm³"};UiKit.addWeightedButton(row,"材料移除證據"){status.text="REMOVED ${"%.3f".format(gl.removedVolumeMm3())} mm³ • NUMERIC"};root.addView(row)}else if(axes.isNotEmpty()){val c=UiKit.toolGrid(this,axes.size*2);axes.forEach{a->UiKit.addGridButton(c,"$a−"){val p=gl.nudgeAxis(a,-5.0);status.text=pose(name,p,verticalOnly)};UiKit.addGridButton(c,"$a+"){val p=gl.nudgeAxis(a,5.0);status.text=pose(name,p,verticalOnly)}};root.addView(c)};return root};private fun pose(n:String,p:AxisPose,v:Boolean)="$n${if(v)" • VERTICAL ONLY" else ""} • A ${"%.3f".format(p.a)}° • B ${"%.3f".format(p.b)}° • C ${"%.3f".format(p.c)}° • OpenGL ES";private fun offlineAi():View=UiKit.column(this).apply{addView(UiKit.skinBanner(this@MainActivity,UiR.drawable.aig_home,150));addView(UiKit.statusLabel(this@MainActivity,"AI • OFFLINE / DEGRADED • 不阻塞本機 CAD/CAM/NC"));addView(UiKit.panel(this@MainActivity).apply{addView(UiKit.label(this@MainActivity,"AI Provider 尚未連線。離線工程功能維持可用；不顯示假的 AI ONLINE。",15f))},LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f))}}
